INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('C-suite buy-in', '高管層認可；執行委員會支持', 'agreement and support from the highest executives in an organization', '[{"en":"C-suite buy-in is essential for any large-scale transformation.","zh-TW":"C-suite buy-in對任何大規模轉型都是必不可少的。"},{"en":"Present the business case in financial terms to gain C-suite buy-in.","zh-TW":"以財務術語呈現業務案例以獲得高管層認可。"}]', 'expression'),
('call to action', '行動號召', 'a prompt that encourages an audience to take a specific next step', '[{"en":"Every email campaign should have a single clear call to action.","zh-TW":"每個電子郵件活動都應該有一個清晰的行動號召。"},{"en":"A compelling call to action increased our click-through rate by 35%.","zh-TW":"引人注目的行動號召使我們的點擊率提高了35%。"}]', 'expression'),
('capital allocation', '資本分配', 'the process of deciding where to invest or deploy available financial resources', '[{"en":"Disciplined capital allocation is a hallmark of great management teams.","zh-TW":"嚴格的資本分配是優秀管理團隊的標誌。"},{"en":"Review capital allocation annually against strategic priorities.","zh-TW":"每年根據戰略優先事項審查資本分配。"}]', 'business idiom'),
('cash conversion cycle', '現金轉換週期', 'the number of days it takes to convert investments in inventory into cash from sales', '[{"en":"Improving collections reduced our cash conversion cycle by 10 days.","zh-TW":"改善收款將我們的現金轉換週期縮短了10天。"},{"en":"A short cash conversion cycle improves liquidity and financial health.","zh-TW":"較短的現金轉換週期改善了流動性和財務健康。"}]', 'business idiom'),
('client retention', '客戶留存；留住客戶', 'the ability to keep existing customers and prevent them from switching to competitors', '[{"en":"Client retention is five times cheaper than acquiring new customers.","zh-TW":"留住客戶比獲取新客戶便宜五倍。"},{"en":"We measure client retention rate quarterly across all segments.","zh-TW":"我們每季度按所有細分市場衡量客戶留存率。"}]', 'business idiom'),
('consolidate gains', '鞏固成果；穩固優勢', 'to secure and build on progress already made before advancing further', '[{"en":"Consolidate gains from the first quarter before entering new markets.","zh-TW":"在進入新市場之前鞏固第一季度的成果。"},{"en":"Strong teams consolidate gains quickly and are ready for the next challenge.","zh-TW":"強大的團隊迅速鞏固成果並為下一個挑戰做好準備。"}]', 'phrasal verb'),
('contact person', '聯絡人；窗口人員', 'the specific individual responsible for handling communication on a matter', '[{"en":"Please direct all enquiries to your designated contact person.","zh-TW":"請將所有詢問轉交給您指定的聯絡人。"},{"en":"Having a single contact person reduces confusion in client relationships.","zh-TW":"擁有單一聯絡人減少了客戶關係中的混亂。"}]', 'business idiom'),
('content marketing', '內容行銷', 'a strategy of creating valuable content to attract and engage a target audience', '[{"en":"Content marketing generated 60% of our inbound leads last year.","zh-TW":"內容行銷去年為我們帶來了60%的入站潛在客戶。"},{"en":"Great content marketing educates buyers before they contact sales.","zh-TW":"出色的內容行銷在買家聯繫銷售之前就教育了他們。"}]', 'business idiom'),
('data-driven decision', '數據驅動的決策', 'a choice made based on analysis of data rather than intuition or anecdote', '[{"en":"Data-driven decisions reduced our product return rate by 18%.","zh-TW":"數據驅動的決策將我們的產品退貨率降低了18%。"},{"en":"Build a culture of data-driven decisions to stay competitive.","zh-TW":"建立數據驅動決策的文化以保持競爭力。"}]', 'business idiom'),
('dynamic pricing', '動態定價', 'a pricing strategy where prices are adjusted in real time based on demand and other factors', '[{"en":"Dynamic pricing increased revenue per seat on high-demand routes.","zh-TW":"動態定價增加了高需求航線的每座收入。"},{"en":"Be transparent about dynamic pricing to maintain customer trust.","zh-TW":"對動態定價保持透明以維護客戶信任。"}]', 'business idiom'),
('ecosystem play', '生態系統策略；平台生態佈局', 'a strategy of building or joining a network of complementary products and partners', '[{"en":"The ecosystem play attracted 200 partner integrations in one year.","zh-TW":"生態系統策略在一年內吸引了200個合作夥伴整合。"},{"en":"An ecosystem play makes it harder for customers to switch.","zh-TW":"生態系統佈局使客戶更難以轉換。"}]', 'business idiom'),
('fitting room', '', '', '[{"en":"The fitting rooms are at the back of the store.","zh-TW":"試衣間在店的後方。"},{"en":"You can only take three items into the fitting room.","zh-TW":"試衣間一次只能帶三件。"}]', 'phrasal verb'),
('strategic alliance', '', '', '[{"en":"The strategic alliance gave both firms access to new markets.","zh-TW":"策略聯盟讓兩家公司都能進入新市場。"},{"en":"A strategic alliance was signed to share technology.","zh-TW":"簽署了技術共享的策略聯盟協議。"}]', 'phrasal verb'),
('competitive advantage', '', '', '[{"en":"Low costs give them a competitive advantage in the market.","zh-TW":"低成本使他們在市場上具有競爭優勢。"},{"en":"Innovation is the company''s key competitive advantage.","zh-TW":"創新是公司的核心競爭優勢。"}]', 'phrasal verb'),
('board of directors', '', '', '[{"en":"The board of directors approved the acquisition.","zh-TW":"董事會批准了收購計劃。"},{"en":"She was elected to the board of directors last month.","zh-TW":"她上個月當選為董事會成員。"}]', 'phrasal verb'),
('best practice', '', '', '[{"en":"We adopted best practices from leading companies worldwide.","zh-TW":"我們採用了全球領先公司的最佳實踐。"},{"en":"Best practices in cybersecurity should be followed strictly.","zh-TW":"應嚴格遵循網路安全最佳實踐。"}]', 'phrasal verb'),
('change management', '', '', '[{"en":"Change management is critical during mergers.","zh-TW":"變革管理在合併期間至關重要。"},{"en":"The HR team led the change management initiative.","zh-TW":"人力資源團隊主導了變革管理計劃。"}]', 'phrasal verb'),
('risk management', '', '', '[{"en":"Risk management helped the firm avoid costly mistakes.","zh-TW":"風險管理幫助公司避免了代價高昂的錯誤。"},{"en":"A solid risk management process is required by regulators.","zh-TW":"監管機構要求有健全的風險管理流程。"}]', 'phrasal verb'),
('reputation management', '', '', '[{"en":"Reputation management became a priority after the incident.","zh-TW":"事件發生後，聲譽管理成為首要任務。"},{"en":"Social media has made reputation management more challenging.","zh-TW":"社群媒體使聲譽管理更具挑戰性。"}]', 'phrasal verb'),
('talent management', '', '', '[{"en":"Effective talent management reduces costly employee turnover.","zh-TW":"有效的人才管理可減少代價高昂的員工流動。"},{"en":"The firm invested heavily in talent management programs.","zh-TW":"公司在人才管理計劃上投入了大量資金。"}]', 'phrasal verb'),
('supply chain management', '', '', '[{"en":"Supply chain management was disrupted by the pandemic.","zh-TW":"供應鏈管理因疫情而受到干擾。"},{"en":"Efficient supply chain management cuts delivery times.","zh-TW":"高效的供應鏈管理縮短了交貨時間。"}]', 'phrasal verb'),
('agile methodology', '', '', '[{"en":"The team adopted agile methodology to speed up delivery.","zh-TW":"團隊採用敏捷方法論加快交付速度。"},{"en":"Agile methodology encourages continuous feedback and adaptation.","zh-TW":"敏捷方法論鼓勵持續反饋和適應。"}]', 'phrasal verb'),
('lean management', '', '', '[{"en":"Lean management helped the factory cut production waste by 30%.","zh-TW":"精益管理幫助工廠將生產浪費削減了30%。"},{"en":"They implemented lean management to improve workflow.","zh-TW":"他們實施精益管理以改善工作流程。"}]', 'phrasal verb'),
('process optimization', '', '', '[{"en":"Process optimization reduced production time by 20%.","zh-TW":"流程優化將生產時間縮短了20%。"},{"en":"They hired a consultant to lead process optimization efforts.","zh-TW":"他們聘請顧問主導流程優化工作。"}]', 'phrasal verb'),
('organizational chart', '', '', '[{"en":"The organizational chart shows who reports to whom.","zh-TW":"組織架構圖顯示了誰向誰匯報。"},{"en":"The new organizational chart reflects the restructuring.","zh-TW":"新組織架構圖反映了重組情況。"}]', 'phrasal verb'),
('gross profit', '', '', '[{"en":"Gross profit improved due to lower raw material costs.","zh-TW":"由於原材料成本降低，毛利有所改善。"},{"en":"The gross profit margin reached 45% last quarter.","zh-TW":"毛利率上季達到45%。"}]', 'phrasal verb'),
('net profit', '', '', '[{"en":"Net profit for the year was $5.2 million.","zh-TW":"全年淨利潤為520萬美元。"},{"en":"Despite rising costs, net profit held steady.","zh-TW":"儘管成本上升，淨利潤保持穩定。"}]', 'phrasal verb'),
('earnings per share', '', '', '[{"en":"Earnings per share rose to $3.50 this fiscal year.","zh-TW":"本財政年度每股盈餘增至3.50美元。"},{"en":"Analysts expected earnings per share to beat estimates.","zh-TW":"分析師預期每股盈餘將超過預期。"}]', 'phrasal verb'),
('cash flow', '', '', '[{"en":"Strong cash flow allows the company to invest in growth.","zh-TW":"強勁的現金流使公司能夠投資於增長。"},{"en":"The startup struggled with negative cash flow in its first year.","zh-TW":"新創公司在第一年面臨負現金流的困境。"}]', 'phrasal verb'),
('capital expenditure', '', '', '[{"en":"Capital expenditure on new equipment totaled $10 million.","zh-TW":"新設備的資本支出共計1000萬美元。"},{"en":"The board approved a capital expenditure plan for expansion.","zh-TW":"董事會批准了用於擴張的資本支出計劃。"}]', 'phrasal verb'),
('balance sheet', '', '', '[{"en":"The balance sheet showed total assets of $500 million.","zh-TW":"資產負債表顯示總資產為5億美元。"},{"en":"Investors scrutinize the balance sheet for hidden liabilities.","zh-TW":"投資者仔細審查資產負債表以發現隱藏負債。"}]', 'phrasal verb'),
('retained earnings', '', '', '[{"en":"Retained earnings fund future expansion without new debt.","zh-TW":"保留盈餘為未來擴張提供資金，無需新增債務。"},{"en":"The balance sheet showed $30 million in retained earnings.","zh-TW":"資產負債表顯示保留盈餘為3000萬美元。"}]', 'phrasal verb'),
('market capitalization', '', '', '[{"en":"The company''s market capitalization exceeded $100 billion.","zh-TW":"公司市值超過1000億美元。"},{"en":"Market capitalization is calculated by multiplying share price by shares outstanding.","zh-TW":"市值通過股價乘以流通股數來計算。"}]', 'phrasal verb'),
('price-earnings ratio', '', '', '[{"en":"A low price-earnings ratio may signal an undervalued stock.","zh-TW":"低本益比可能表示股票被低估。"},{"en":"The tech sector typically trades at a higher price-earnings ratio.","zh-TW":"科技行業通常以較高的本益比交易。"}]', 'phrasal verb'),
('hedge fund', '', '', '[{"en":"The hedge fund delivered 20% returns last year.","zh-TW":"對沖基金去年實現了20%的回報。"},{"en":"Hedge funds often use leverage to amplify returns.","zh-TW":"對沖基金經常使用槓桿來放大回報。"}]', 'phrasal verb'),
('private equity', '', '', '[{"en":"The private equity firm acquired a stake in the startup.","zh-TW":"私募股權公司收購了這家新創公司的股份。"},{"en":"Private equity investors typically seek returns over 5-7 years.","zh-TW":"私募股權投資者通常在5-7年內尋求回報。"}]', 'phrasal verb'),
('venture capital', '', '', '[{"en":"The startup secured $5 million in venture capital.","zh-TW":"這家新創公司獲得了500萬美元的創業投資。"},{"en":"Venture capital investors often take a board seat.","zh-TW":"創業投資者通常獲得董事會席位。"}]', 'phrasal verb'),
('asset allocation', '', '', '[{"en":"Asset allocation determines the risk-return profile of a portfolio.","zh-TW":"資產配置決定了投資組合的風險回報特徵。"},{"en":"She adjusted her asset allocation as she neared retirement.","zh-TW":"她在接近退休時調整了資產配置。"}]', 'phrasal verb'),
('interest rate', '', '', '[{"en":"The central bank raised interest rates to combat inflation.","zh-TW":"中央銀行提高利率以對抗通貨膨脹。"},{"en":"Low interest rates encouraged businesses to borrow more.","zh-TW":"低利率鼓勵企業增加借貸。"}]', 'phrasal verb'),
('fiscal policy', '', '', '[{"en":"Expansionary fiscal policy helped stimulate economic growth.","zh-TW":"擴張性財政政策有助於刺激經濟增長。"},{"en":"The government''s fiscal policy focused on reducing the deficit.","zh-TW":"政府的財政政策著重於減少赤字。"}]', 'phrasal verb'),
('monetary policy', '', '', '[{"en":"The central bank tightened monetary policy to cool inflation.","zh-TW":"中央銀行收緊貨幣政策以遏制通貨膨脹。"},{"en":"Monetary policy decisions affect borrowing costs nationwide.","zh-TW":"貨幣政策決定影響全國的借貸成本。"}]', 'phrasal verb'),
('fixed asset', '', '', '[{"en":"Machinery and buildings are examples of fixed assets.","zh-TW":"機械和建築物是固定資產的例子。"},{"en":"Fixed assets are depreciated over their useful life.","zh-TW":"固定資產在其使用壽命內進行折舊。"}]', 'phrasal verb'),
('intangible asset', '', '', '[{"en":"Brands and patents are valuable intangible assets.","zh-TW":"品牌和專利是有價值的無形資產。"},{"en":"Intangible assets are often harder to value than physical ones.","zh-TW":"無形資產通常比有形資產更難估值。"}]', 'phrasal verb'),
('deferred tax', '', '', '[{"en":"A deferred tax liability arose from accelerated depreciation.","zh-TW":"加速折舊導致了遞延所得稅負債。"},{"en":"Deferred tax assets were recognized based on future income projections.","zh-TW":"根據未來收入預測確認了遞延所得稅資產。"}]', 'phrasal verb'),
('bull market', '', '', '[{"en":"The bull market lasted five years before the correction.","zh-TW":"牛市在調整前持續了五年。"},{"en":"Investors thrived during the long bull market.","zh-TW":"投資者在漫長的牛市中蓬勃發展。"}]', 'phrasal verb'),
('bear market', '', '', '[{"en":"The bear market wiped out years of gains.","zh-TW":"熊市抹去了多年的收益。"},{"en":"Defensive stocks performed better during the bear market.","zh-TW":"防禦型股票在熊市中表現較好。"}]', 'phrasal verb'),
('seed funding', '', '', '[{"en":"They raised $500,000 in seed funding to develop the app.","zh-TW":"他們籌集了50萬美元的種子輪融資來開發應用程式。"},{"en":"Seed funding typically comes from angel investors or accelerators.","zh-TW":"種子輪融資通常來自天使投資人或加速器。"}]', 'phrasal verb'),
('angel investor', '', '', '[{"en":"An angel investor provided the initial capital to launch the company.","zh-TW":"天使投資人提供了啟動公司的初始資本。"},{"en":"Angel investors often provide mentorship in addition to funding.","zh-TW":"天使投資人除了資金外，通常還提供指導。"}]', 'phrasal verb'),
('forward contract', '', '', '[{"en":"They used a forward contract to lock in the exchange rate.","zh-TW":"他們使用遠期合約鎖定匯率。"},{"en":"A forward contract eliminates price uncertainty for both parties.","zh-TW":"遠期合約消除了雙方的價格不確定性。"}]', 'phrasal verb'),
('stock option', '', '', '[{"en":"The startup offered generous stock options to attract engineers.","zh-TW":"新創公司提供豐厚的股票選擇權吸引工程師。"},{"en":"Stock options vest over a four-year period.","zh-TW":"股票選擇權在四年內歸屬。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('non-compete clause', '', '', '[{"en":"The non-compete clause prevented him from joining a rival for two years.","zh-TW":"競業禁止條款阻止他在兩年內加入競爭對手。"},{"en":"Courts sometimes invalidate overly broad non-compete clauses.","zh-TW":"法院有時會宣告過於廣泛的競業禁止條款無效。"}]', 'phrasal verb'),
('employee engagement', '', '', '[{"en":"High employee engagement leads to better productivity and retention.","zh-TW":"高員工投入度帶來更好的生產力和留才率。"},{"en":"The annual engagement survey revealed areas for improvement.","zh-TW":"年度投入度調查揭示了需要改進的領域。"}]', 'phrasal verb'),
('work-life balance', '', '', '[{"en":"Flexible hours help employees maintain a healthy work-life balance.","zh-TW":"彈性工時幫助員工保持健康的工作與生活平衡。"},{"en":"Poor work-life balance leads to burnout and high turnover.","zh-TW":"工作與生活失衡導致職業倦怠和高流動率。"}]', 'phrasal verb'),
('remote work', '', '', '[{"en":"Remote work became widespread during the pandemic.","zh-TW":"疫情期間，遠端工作變得普遍。"},{"en":"The company offers remote work options to attract global talent.","zh-TW":"公司提供遠端工作選項以吸引全球人才。"}]', 'phrasal verb'),
('hybrid work', '', '', '[{"en":"The company adopted a hybrid work model of three days in office.","zh-TW":"公司採用了每週三天辦公室的混合工作模式。"},{"en":"Hybrid work arrangements offer flexibility while maintaining team cohesion.","zh-TW":"混合工作安排提供靈活性，同時保持團隊凝聚力。"}]', 'phrasal verb'),
('flexible working', '', '', '[{"en":"Flexible working arrangements improved employee satisfaction.","zh-TW":"彈性工時安排提高了員工滿意度。"},{"en":"She requested flexible working to manage childcare responsibilities.","zh-TW":"她申請彈性工時以管理育兒責任。"}]', 'phrasal verb'),
('maternity leave', '', '', '[{"en":"She took 12 weeks of paid maternity leave after her baby was born.","zh-TW":"孩子出生後，她休了12週的有薪產假。"},{"en":"The company extended maternity leave to 26 weeks.","zh-TW":"公司將產假延長至26週。"}]', 'phrasal verb'),
('parental leave', '', '', '[{"en":"Both parents are entitled to parental leave under the new policy.","zh-TW":"根據新政策，雙方父母均有權休育嬰假。"},{"en":"More companies are offering extended parental leave as a benefit.","zh-TW":"越來越多的公司將延長育嬰假作為福利提供。"}]', 'phrasal verb'),
('health insurance', '', '', '[{"en":"The company provides comprehensive health insurance for all employees.","zh-TW":"公司為所有員工提供全面的健康保險。"},{"en":"Health insurance is one of the most valued employee benefits.","zh-TW":"健康保險是最受重視的員工福利之一。"}]', 'phrasal verb'),
('paid time off', '', '', '[{"en":"Employees receive 20 days of paid time off per year.","zh-TW":"員工每年有20天有薪假期。"},{"en":"She used her paid time off to travel abroad.","zh-TW":"她用有薪假期出國旅遊。"}]', 'phrasal verb'),
('probationary period', '', '', '[{"en":"New employees are subject to a three-month probationary period.","zh-TW":"新員工須接受三個月的試用期。"},{"en":"She passed her probationary period with excellent reviews.","zh-TW":"她以優異的評價通過了試用期。"}]', 'phrasal verb'),
('notice period', '', '', '[{"en":"She served a two-week notice period before leaving.","zh-TW":"她在離職前履行了兩週的通知期。"},{"en":"The contract required a three-month notice period.","zh-TW":"合同要求三個月的通知期。"}]', 'phrasal verb'),
('employment contract', '', '', '[{"en":"She signed the employment contract before her start date.","zh-TW":"她在入職日期前簽署了僱傭合約。"},{"en":"The employment contract specifies salary, duties, and benefits.","zh-TW":"僱傭合約規定了薪資、職責和福利。"}]', 'phrasal verb'),
('collective bargaining', '', '', '[{"en":"Collective bargaining resulted in higher wages for factory workers.","zh-TW":"集體談判為工廠工人爭取到了更高的工資。"},{"en":"The union entered collective bargaining to improve working conditions.","zh-TW":"工會進行集體談判以改善工作條件。"}]', 'phrasal verb'),
('trade union', '', '', '[{"en":"The trade union negotiated a 5% pay increase for its members.","zh-TW":"工會為其成員談判獲得5%的薪資增幅。"},{"en":"Trade unions play a key role in protecting workers'' rights.","zh-TW":"工會在保護工人權利方面發揮著關鍵作用。"}]', 'phrasal verb'),
('360-degree feedback', '', '', '[{"en":"The 360-degree feedback revealed blind spots in leadership style.","zh-TW":"360度反饋揭示了領導風格中的盲點。"},{"en":"Employees appreciate 360-degree feedback for its balanced perspective.","zh-TW":"員工欣賞360度反饋的平衡視角。"}]', 'phrasal verb'),
('salary band', '', '', '[{"en":"The new hire''s salary fell within the band for that job grade.","zh-TW":"新員工的薪資在該職等的薪資範圍內。"},{"en":"Transparent salary bands promote fairness across the organization.","zh-TW":"透明的薪資範圍促進了組織內部的公平性。"}]', 'phrasal verb'),
('pay equity', '', '', '[{"en":"The company conducted a pay equity audit to close wage gaps.","zh-TW":"公司進行了薪酬公平審計以縮小薪資差距。"},{"en":"Pay equity initiatives are increasingly required by law.","zh-TW":"薪酬公平倡議越來越多地被法律所要求。"}]', 'phrasal verb'),
('gender pay gap', '', '', '[{"en":"The company published its gender pay gap report as required by law.","zh-TW":"公司按法律要求發布了性別薪資差距報告。"},{"en":"Addressing the gender pay gap requires systemic organizational change.","zh-TW":"解決性別薪資差距需要系統性的組織變革。"}]', 'phrasal verb'),
('background check', '', '', '[{"en":"All applicants must pass a background check before being hired.","zh-TW":"所有申請者在被錄用前必須通過背景調查。"},{"en":"The background check revealed a discrepancy in the resume.","zh-TW":"背景調查發現了簡歷中的差異。"}]', 'phrasal verb'),
('job description', '', '', '[{"en":"The job description listed the required skills and experience.","zh-TW":"職位描述列出了所需的技能和經驗。"},{"en":"A clear job description helps attract the right candidates.","zh-TW":"清晰的職位描述有助於吸引合適的候選人。"}]', 'phrasal verb'),
('offer letter', '', '', '[{"en":"She received an offer letter with a generous compensation package.","zh-TW":"她收到了一封附有豐厚薪酬方案的錄取通知書。"},{"en":"The offer letter outlined the start date, salary, and benefits.","zh-TW":"錄取通知書說明了入職日期、薪資和福利。"}]', 'phrasal verb'),
('brand awareness', '', '', '[{"en":"The campaign significantly increased brand awareness among millennials.","zh-TW":"該活動顯著提高了千禧世代對品牌的認知。"},{"en":"Social media is an effective tool for building brand awareness.","zh-TW":"社群媒體是建立品牌知名度的有效工具。"}]', 'phrasal verb'),
('brand ambassador', '', '', '[{"en":"The athlete became a brand ambassador for the sportswear company.","zh-TW":"這位運動員成為了運動服裝公司的品牌大使。"},{"en":"Brand ambassadors help humanize the company''s image.","zh-TW":"品牌大使幫助使公司形象更加人性化。"}]', 'phrasal verb'),
('market segmentation', '', '', '[{"en":"Market segmentation helped the company tailor its messaging.","zh-TW":"市場細分幫助公司量身訂製其訊息傳遞。"},{"en":"Geographic market segmentation drives localized marketing strategies.","zh-TW":"地理市場細分推動了本地化行銷策略。"}]', 'phrasal verb'),
('buyer persona', '', '', '[{"en":"Understanding your buyer persona improves targeting accuracy.","zh-TW":"了解買家人物誌提高了目標定位的準確性。"},{"en":"The marketing team developed three distinct buyer personas.","zh-TW":"行銷團隊開發了三個不同的買家人物誌。"}]', 'phrasal verb'),
('lead generation', '', '', '[{"en":"Content marketing is effective for lead generation.","zh-TW":"內容行銷對潛在客戶開發很有效。"},{"en":"The lead generation campaign added 500 prospects to the pipeline.","zh-TW":"潛在客戶開發活動為銷售漏斗增加了500個潛在客戶。"}]', 'phrasal verb'),
('influencer marketing', '', '', '[{"en":"The brand''s influencer marketing campaign went viral.","zh-TW":"該品牌的網紅行銷活動爆紅。"},{"en":"Micro-influencer marketing often yields higher engagement rates.","zh-TW":"微型網紅行銷通常產生更高的互動率。"}]', 'phrasal verb'),
('email marketing', '', '', '[{"en":"Their email marketing campaign achieved a 25% open rate.","zh-TW":"他們的電子郵件行銷活動達到了25%的開信率。"},{"en":"Personalized email marketing improves click-through rates.","zh-TW":"個人化電子郵件行銷提高了點擊率。"}]', 'phrasal verb'),
('value-added reseller', '', '', '[{"en":"The software firm built a network of value-added resellers.","zh-TW":"軟體公司建立了增值經銷商網路。"},{"en":"Value-added resellers provide implementation support alongside the product.","zh-TW":"增值經銷商在產品旁邊提供實施支援。"}]', 'phrasal verb'),
('pricing strategy', '', '', '[{"en":"The company''s pricing strategy targets cost-conscious consumers.","zh-TW":"公司的定價策略針對注重成本的消費者。"},{"en":"Dynamic pricing strategy adjusts prices based on demand.","zh-TW":"動態定價策略根據需求調整價格。"}]', 'phrasal verb'),
('marketing automation', '', '', '[{"en":"Marketing automation streamlines lead nurturing campaigns.","zh-TW":"行銷自動化簡化了潛在客戶培育活動。"},{"en":"The team uses marketing automation to send personalized emails at scale.","zh-TW":"團隊使用行銷自動化大規模發送個人化電子郵件。"}]', 'phrasal verb'),
('click-through rate', '', '', '[{"en":"The new subject line doubled the email''s click-through rate.","zh-TW":"新的主旨行使電子郵件的點擊率翻倍。"},{"en":"A higher click-through rate indicates more engaging ad copy.","zh-TW":"更高的點擊率表示更吸引人的廣告文案。"}]', 'phrasal verb'),
('A/B testing', '', '', '[{"en":"A/B testing showed that the red button outperformed the green one.","zh-TW":"A/B測試顯示紅色按鈕的表現優於綠色按鈕。"},{"en":"We use A/B testing to optimize our landing pages.","zh-TW":"我們使用A/B測試優化登陸頁面。"}]', 'phrasal verb'),
('public relations', '', '', '[{"en":"The public relations team managed the crisis communication effectively.","zh-TW":"公關團隊有效地管理了危機溝通。"},{"en":"Strong public relations can rebuild a damaged brand reputation.","zh-TW":"強大的公共關係可以重建受損的品牌聲譽。"}]', 'phrasal verb'),
('press release', '', '', '[{"en":"The company issued a press release announcing the new product launch.","zh-TW":"公司發布了宣布新產品上市的新聞稿。"},{"en":"A well-crafted press release can generate significant media coverage.","zh-TW":"一份精心撰寫的新聞稿可以產生重大的媒體報導。"}]', 'phrasal verb'),
('thought leadership', '', '', '[{"en":"Publishing white papers helped the firm build thought leadership.","zh-TW":"發布白皮書幫助公司建立了思想領袖地位。"},{"en":"Thought leadership attracts both customers and top talent.","zh-TW":"思想領袖地位吸引了客戶和頂尖人才。"}]', 'phrasal verb'),
('loyalty program', '', '', '[{"en":"The loyalty program increased repeat purchase rates by 35%.","zh-TW":"忠誠度計劃使重複購買率提高了35%。"},{"en":"Customers earn points through the loyalty program with each purchase.","zh-TW":"客戶通過忠誠度計劃每次購買都能獲得積分。"}]', 'phrasal verb'),
('cold calling', '', '', '[{"en":"Cold calling remains a core tactic for B2B sales teams.","zh-TW":"冷電話仍然是B2B銷售團隊的核心策略。"},{"en":"He made 50 cold calls a day during the initial sales push.","zh-TW":"在最初的銷售衝刺期間，他每天打50個冷電話。"}]', 'phrasal verb'),
('account management', '', '', '[{"en":"Strong account management is key to customer retention.","zh-TW":"強大的客戶管理是客戶保留的關鍵。"},{"en":"The account management team meets clients quarterly to review performance.","zh-TW":"帳戶管理團隊每季與客戶會面以審查績效。"}]', 'phrasal verb'),
('trade show', '', '', '[{"en":"The company showcased its new product at the annual trade show.","zh-TW":"公司在年度貿易展上展示了新產品。"},{"en":"Trade shows are great for networking with industry peers.","zh-TW":"貿易展是與業界同行建立人際關係的好機會。"}]', 'phrasal verb'),
('attribution model', '', '', '[{"en":"The attribution model showed that email drove most conversions.","zh-TW":"歸因模型顯示電子郵件推動了最多的轉換。"},{"en":"Choosing the right attribution model is critical for measuring ROI.","zh-TW":"選擇正確的歸因模型對衡量投資報酬率至關重要。"}]', 'phrasal verb'),
('product launch', '', '', '[{"en":"The product launch generated significant media buzz.","zh-TW":"產品發佈引起了大量媒體關注。"},{"en":"A soft launch was planned before the full product launch.","zh-TW":"在全面產品發佈前計劃了軟啟動。"}]', 'phrasal verb'),
('target market', '', '', '[{"en":"The campaign was designed specifically for our target market of young professionals.","zh-TW":"該活動專門為我們的年輕專業人士目標市場設計。"},{"en":"Understanding your target market is the foundation of marketing strategy.","zh-TW":"了解目標市場是行銷策略的基礎。"}]', 'phrasal verb'),
('action item', '', '', '[{"en":"Each action item was assigned to a specific team member.","zh-TW":"每個行動事項都分配給了特定的團隊成員。"},{"en":"Outstanding action items were reviewed at the start of the meeting.","zh-TW":"未完成的行動事項在會議開始時進行了審查。"}]', 'phrasal verb'),
('risk register', '', '', '[{"en":"The risk register was updated after the supplier delayed delivery.","zh-TW":"供應商延遲交貨後，風險登記冊進行了更新。"},{"en":"All project risks are documented in the risk register.","zh-TW":"所有項目風險都記錄在風險登記冊中。"}]', 'phrasal verb'),
('purchase order', '', '', '[{"en":"A purchase order was raised for the new office furniture.","zh-TW":"為新辦公室家具開立了採購訂單。"},{"en":"Payment will be processed once the purchase order is approved.","zh-TW":"採購訂單獲批後將處理付款。"}]', 'phrasal verb'),
('contract management', '', '', '[{"en":"Contract management software automates renewal reminders.","zh-TW":"合約管理軟體自動提醒續約。"},{"en":"Poor contract management can lead to missed obligations.","zh-TW":"糟糕的合約管理可能導致錯過義務。"}]', 'phrasal verb'),
('root cause analysis', '', '', '[{"en":"Root cause analysis revealed a software bug caused the outage.","zh-TW":"根本原因分析顯示軟體錯誤導致了中斷。"},{"en":"The team used root cause analysis to prevent recurrence.","zh-TW":"團隊使用根本原因分析防止問題再次發生。"}]', 'phrasal verb'),
('standard operating procedure', '', '', '[{"en":"The standard operating procedure ensures consistent product quality.","zh-TW":"標準作業程序確保一致的產品品質。"},{"en":"New employees are trained on the standard operating procedures.","zh-TW":"新員工接受標準作業程序培訓。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('KPI dashboard', '', '', '[{"en":"The KPI dashboard gives executives a real-time view of performance.","zh-TW":"關鍵績效指標儀表板為高管提供績效的即時視圖。"},{"en":"All departments share a common KPI dashboard.","zh-TW":"所有部門共用一個共同的KPI儀表板。"}]', 'phrasal verb'),
('user acceptance testing', '', '', '[{"en":"User acceptance testing uncovered several usability issues.","zh-TW":"用戶驗收測試發現了幾個可用性問題。"},{"en":"The product cannot go live until it passes user acceptance testing.","zh-TW":"產品在通過用戶驗收測試之前不能上線。"}]', 'phrasal verb'),
('project charter', '', '', '[{"en":"The project charter was signed by the sponsor before kickoff.","zh-TW":"項目章程在啟動前由贊助人簽署。"},{"en":"A clear project charter aligns stakeholders from the start.","zh-TW":"清晰的項目章程從一開始就使利益相關者保持一致。"}]', 'phrasal verb'),
('kickoff meeting', '', '', '[{"en":"The kickoff meeting set expectations for the entire project.","zh-TW":"啟動會議為整個項目設定了期望。"},{"en":"All stakeholders attended the project kickoff meeting.","zh-TW":"所有利益相關者出席了項目啟動會議。"}]', 'phrasal verb'),
('change request', '', '', '[{"en":"Any new requirement must be submitted as a change request.","zh-TW":"任何新需求都必須以變更請求的形式提交。"},{"en":"The client''s change request added three weeks to the schedule.","zh-TW":"客戶的變更請求在排程上增加了三週。"}]', 'phrasal verb'),
('lessons learned', '', '', '[{"en":"The lessons learned document will guide future similar projects.","zh-TW":"經驗教訓文件將指導未來類似的項目。"},{"en":"Sharing lessons learned prevents repeating the same mistakes.","zh-TW":"分享經驗教訓可防止重複相同的錯誤。"}]', 'phrasal verb'),
('fiscal year', '', '', '[{"en":"The company''s fiscal year runs from April to March.","zh-TW":"公司的財政年度從四月到三月。"},{"en":"Results are reported at the end of each fiscal year.","zh-TW":"業績在每個財政年度末報告。"}]', 'phrasal verb'),
('cost reduction', '', '', '[{"en":"The cost reduction program saved $10 million annually.","zh-TW":"成本削減計劃每年節省了1000萬美元。"},{"en":"Automation is the primary driver of cost reduction in manufacturing.","zh-TW":"自動化是製造業成本削減的主要驅動力。"}]', 'phrasal verb'),
('cost of goods sold', '', '', '[{"en":"Cost of goods sold increased due to rising material prices.","zh-TW":"由於材料價格上漲，銷貨成本增加了。"},{"en":"Gross profit is revenue minus cost of goods sold.","zh-TW":"毛利是收入減去銷貨成本。"}]', 'phrasal verb'),
('operating expenses', '', '', '[{"en":"Operating expenses were kept below 30% of revenue.","zh-TW":"營運費用保持在收入的30%以下。"},{"en":"Reducing operating expenses directly improves operating profit.","zh-TW":"降低營運費用直接改善了營業利潤。"}]', 'phrasal verb'),
('working capital management', '', '', '[{"en":"Effective working capital management prevents cash flow crises.","zh-TW":"有效的營運資金管理可防止現金流危機。"},{"en":"Inventory optimization is a core part of working capital management.","zh-TW":"庫存優化是營運資金管理的核心部分。"}]', 'phrasal verb'),
('capital structure', '', '', '[{"en":"The acquisition changed the company''s capital structure significantly.","zh-TW":"收購顯著改變了公司的資本結構。"},{"en":"A balanced capital structure minimizes the cost of capital.","zh-TW":"平衡的資本結構最小化了資本成本。"}]', 'phrasal verb'),
('financial modeling', '', '', '[{"en":"Financial modeling is essential for evaluating acquisition targets.","zh-TW":"財務建模對評估收購目標至關重要。"},{"en":"The analyst used financial modeling to project five-year cash flows.","zh-TW":"分析師使用財務建模預測了五年現金流。"}]', 'phrasal verb'),
('credit rating', '', '', '[{"en":"The firm''s credit rating was downgraded after the profit warning.","zh-TW":"公司在發出盈利警告後，信用評級被下調。"},{"en":"A strong credit rating lowers borrowing costs for businesses.","zh-TW":"強勁的信用評級降低了企業的借貸成本。"}]', 'phrasal verb'),
('interest coverage ratio', '', '', '[{"en":"A high interest coverage ratio indicates financial stability.","zh-TW":"高利息覆蓋率表明財務穩定性。"},{"en":"The company''s interest coverage ratio fell below 2, triggering concern.","zh-TW":"公司的利息覆蓋率跌破2，引發擔憂。"}]', 'phrasal verb'),
('debt-to-equity ratio', '', '', '[{"en":"A high debt-to-equity ratio may signal financial risk.","zh-TW":"高負債股權比率可能表示財務風險。"},{"en":"The firm reduced its debt-to-equity ratio through share issuance.","zh-TW":"公司通過發行股票降低了負債股權比率。"}]', 'phrasal verb'),
('accrued expense', '', '', '[{"en":"Wages earned but unpaid at month-end are accrued expenses.","zh-TW":"月末已賺取但未支付的工資是應計費用。"},{"en":"The accountant reviewed all accrued expenses before closing.","zh-TW":"會計師在結帳前審查了所有應計費用。"}]', 'phrasal verb'),
('prepaid expense', '', '', '[{"en":"Insurance premiums paid upfront are recorded as prepaid expenses.","zh-TW":"預先支付的保險費記錄為預付費用。"},{"en":"Prepaid expenses are classified as current assets on the balance sheet.","zh-TW":"預付費用在資產負債表上被列為流動資產。"}]', 'phrasal verb'),
('deferred revenue', '', '', '[{"en":"Subscription fees received upfront are recorded as deferred revenue.","zh-TW":"預先收取的訂閱費記錄為遞延收入。"},{"en":"As services are delivered, deferred revenue is recognized as income.","zh-TW":"隨著服務的交付，遞延收入被確認為收入。"}]', 'phrasal verb'),
('annual report', '', '', '[{"en":"The annual report highlighted strong revenue growth year over year.","zh-TW":"年報強調了年度收入的強勁增長。"},{"en":"Shareholders receive the annual report before the AGM.","zh-TW":"股東在年度股東大會前收到年報。"}]', 'phrasal verb'),
('quarterly report', '', '', '[{"en":"The quarterly report beat analyst expectations by 15%.","zh-TW":"季報超出分析師預期15%。"},{"en":"Investors analyze quarterly reports to track company performance.","zh-TW":"投資者分析季報以追蹤公司績效。"}]', 'phrasal verb'),
('advisory board', '', '', '[{"en":"The startup assembled an advisory board of industry veterans.","zh-TW":"新創公司組建了由行業老手組成的顧問委員會。"},{"en":"The advisory board provided valuable insights on market expansion.","zh-TW":"顧問委員會提供了有關市場擴張的寶貴見解。"}]', 'phrasal verb'),
('task force', '', '', '[{"en":"A task force was formed to address the supply chain disruptions.","zh-TW":"成立了一個特別工作組以應對供應鏈中斷問題。"},{"en":"The task force delivered its recommendations within 30 days.","zh-TW":"特別工作組在30天內提交了建議。"}]', 'phrasal verb'),
('working group', '', '', '[{"en":"The working group developed new data privacy guidelines.","zh-TW":"工作組制定了新的資料隱私指南。"},{"en":"Several working groups were formed to study the policy options.","zh-TW":"成立了幾個工作組研究政策選項。"}]', 'phrasal verb'),
('reporting line', '', '', '[{"en":"His reporting line was changed after the reorganization.","zh-TW":"他的匯報關係在重組後發生了變化。"},{"en":"A clear reporting line prevents confusion about authority.","zh-TW":"清晰的匯報關係防止了對授權的混淆。"}]', 'phrasal verb'),
('total quality management', '', '', '[{"en":"Total quality management helped reduce defect rates to near zero.","zh-TW":"全面品質管理幫助將缺陷率降至接近零。"},{"en":"TQM requires commitment from every level of the organization.","zh-TW":"全面品質管理需要組織每個層級的承諾。"}]', 'phrasal verb'),
('project management', '', '', '[{"en":"Strong project management kept the initiative on time and on budget.","zh-TW":"強大的項目管理使計劃按時按預算完成。"},{"en":"She earned a project management certification to advance her career.","zh-TW":"她獲得了項目管理認證以推進職業生涯。"}]', 'phrasal verb'),
('knowledge management', '', '', '[{"en":"A knowledge management system reduces time spent searching for information.","zh-TW":"知識管理系統減少了搜索信息所花費的時間。"},{"en":"Knowledge management is critical when key staff leave the company.","zh-TW":"當關鍵員工離開公司時，知識管理至關重要。"}]', 'phrasal verb'),
('operations management', '', '', '[{"en":"Operations management ensures products are delivered on time and within cost.","zh-TW":"營運管理確保產品按時按成本交付。"},{"en":"He studied operations management to improve supply chain efficiency.","zh-TW":"他學習了營運管理以提高供應鏈效率。"}]', 'phrasal verb'),
('facilities management', '', '', '[{"en":"Facilities management ensures a safe and productive work environment.","zh-TW":"設施管理確保安全且有生產力的工作環境。"},{"en":"The facilities management team handled the office relocation.","zh-TW":"設施管理團隊處理了辦公室搬遷。"}]', 'phrasal verb'),
('salary negotiation', '', '', '[{"en":"She researched market rates before entering salary negotiation.","zh-TW":"她在進入薪資談判前研究了市場薪資水準。"},{"en":"Salary negotiation is an expected part of the hiring process.","zh-TW":"薪資談判是招聘過程中的預期環節。"}]', 'phrasal verb'),
('total rewards', '', '', '[{"en":"The total rewards package includes health, wellness, and financial benefits.","zh-TW":"全面薪酬方案包括健康、健康和財務福利。"},{"en":"A competitive total rewards strategy helps attract top talent.","zh-TW":"具競爭力的全面薪酬策略有助於吸引頂尖人才。"}]', 'phrasal verb'),
('variable pay', '', '', '[{"en":"Variable pay aligned employee incentives with company performance.","zh-TW":"績效薪酬將員工激勵與公司績效保持一致。"},{"en":"Variable pay can make up 30% of total compensation for sales roles.","zh-TW":"銷售職位的績效薪酬可佔總薪酬的30%。"}]', 'phrasal verb'),
('equity grant', '', '', '[{"en":"The equity grant vests over four years with a one-year cliff.","zh-TW":"股權授予在四年內歸屬，並有一年的懸崖期。"},{"en":"Equity grants align employee interests with company performance.","zh-TW":"股權授予使員工利益與公司績效保持一致。"}]', 'phrasal verb'),
('disciplinary action', '', '', '[{"en":"The manager took disciplinary action after repeated tardiness.","zh-TW":"員工多次遲到後，主管採取了紀律處分。"},{"en":"A written warning is typically the first step in disciplinary action.","zh-TW":"書面警告通常是紀律處分的第一步。"}]', 'phrasal verb'),
('constructive dismissal', '', '', '[{"en":"She claimed constructive dismissal after her responsibilities were stripped away.","zh-TW":"她在職責被剝奪後提出了逼迫辭職的主張。"},{"en":"Constructive dismissal claims are difficult but winnable in court.","zh-TW":"逼迫辭職索賠在法庭上很困難但可以勝訴。"}]', 'phrasal verb'),
('affirmative action', '', '', '[{"en":"Affirmative action policies increased diversity in the workforce.","zh-TW":"積極差別待遇政策增加了勞動力的多元性。"},{"en":"The company adopted affirmative action measures in its hiring process.","zh-TW":"公司在招聘流程中採用了積極差別待遇措施。"}]', 'phrasal verb'),
('labor law', '', '', '[{"en":"The company updated its policies to comply with new labor laws.","zh-TW":"公司更新了其政策以遵守新勞動法。"},{"en":"Labor law violations can result in significant fines.","zh-TW":"違反勞動法可能導致重大罰款。"}]', 'phrasal verb'),
('employment law', '', '', '[{"en":"The HR team consulted an employment law expert before the restructuring.","zh-TW":"人力資源團隊在重組前諮詢了就業法專家。"},{"en":"Understanding employment law is essential for all managers.","zh-TW":"了解就業法對所有管理者至關重要。"}]', 'phrasal verb'),
('performance management', '', '', '[{"en":"The performance management system was redesigned to be more frequent and actionable.","zh-TW":"績效管理系統被重新設計為更頻繁且可行動的。"},{"en":"Performance management aligns individual goals with company strategy.","zh-TW":"績效管理將個人目標與公司策略保持一致。"}]', 'phrasal verb'),
('constructive feedback', '', '', '[{"en":"Managers are trained to deliver constructive feedback effectively.","zh-TW":"管理者接受培訓以有效提供建設性反饋。"},{"en":"Constructive feedback helped her improve her presentation skills.","zh-TW":"建設性反饋幫助她改善了演講技巧。"}]', 'phrasal verb'),
('relocation package', '', '', '[{"en":"The relocation package covered moving costs and temporary housing.","zh-TW":"搬遷方案涵蓋搬遷費用和臨時住房。"},{"en":"She accepted the job offer partly because of the generous relocation package.","zh-TW":"她接受工作邀請部分原因是豐厚的搬遷方案。"}]', 'phrasal verb'),
('brand guidelines', '', '', '[{"en":"All marketing materials must adhere to the brand guidelines.","zh-TW":"所有行銷材料必須遵守品牌指南。"},{"en":"The brand guidelines specify approved fonts, colors, and logo usage.","zh-TW":"品牌指南規定了批准的字體、顏色和標誌使用方式。"}]', 'phrasal verb'),
('lead nurturing', '', '', '[{"en":"Lead nurturing emails guide prospects through the buying journey.","zh-TW":"潛在客戶培育電子郵件引導潛在客戶完成購買旅程。"},{"en":"Personalized lead nurturing improves conversion rates significantly.","zh-TW":"個人化潛在客戶培育顯著提高了轉換率。"}]', 'phrasal verb'),
('warm lead', '', '', '[{"en":"Warm leads are far more likely to convert than cold ones.","zh-TW":"暖潛在客戶比冷潛在客戶更有可能轉換。"},{"en":"She focused on warm leads to shorten the sales cycle.","zh-TW":"她專注於暖潛在客戶以縮短銷售週期。"}]', 'phrasal verb'),
('cost per click', '', '', '[{"en":"The campaign achieved a cost per click of $0.50.","zh-TW":"該活動實現了每次點擊0.50美元的費用。"},{"en":"A/B testing reduced cost per click by 25%.","zh-TW":"A/B測試將每次點擊費用降低了25%。"}]', 'phrasal verb'),
('cost per acquisition', '', '', '[{"en":"The cost per acquisition dropped after optimizing the landing page.","zh-TW":"優化登陸頁面後，每次轉換費用下降了。"},{"en":"Tracking cost per acquisition helps allocate marketing budget effectively.","zh-TW":"追蹤每次轉換費用有助於有效分配行銷預算。"}]', 'phrasal verb'),
('landing page', '', '', '[{"en":"The landing page had a clear call to action and minimal distractions.","zh-TW":"登陸頁有清晰的行動號召且干擾極少。"},{"en":"A well-designed landing page can dramatically improve conversion rates.","zh-TW":"精心設計的登陸頁可以顯著提高轉換率。"}]', 'phrasal verb'),
('affiliate marketing', '', '', '[{"en":"The company generated 20% of sales through affiliate marketing.","zh-TW":"公司通過聯盟行銷產生了20%的銷售額。"},{"en":"Affiliate marketing is a cost-effective way to expand reach.","zh-TW":"聯盟行銷是擴大覆蓋範圍的具成本效益方式。"}]', 'phrasal verb'),
('social media marketing', '', '', '[{"en":"Social media marketing drives brand awareness among younger consumers.","zh-TW":"社群媒體行銷在年輕消費者中提高了品牌知名度。"},{"en":"A consistent social media marketing presence builds trust over time.","zh-TW":"持續的社群媒體行銷存在隨時間建立信任。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('paid search', '', '', '[{"en":"Paid search delivered immediate traffic to the newly launched site.","zh-TW":"付費搜尋廣告為新推出的網站立即帶來了流量。"},{"en":"Paid search and organic SEO should work together for maximum impact.","zh-TW":"付費搜尋和自然SEO應一起發揮最大效果。"}]', 'phrasal verb'),
('customer experience', '', '', '[{"en":"Investing in customer experience led to a 25% increase in loyalty.","zh-TW":"投資客戶體驗帶來了25%的忠誠度提升。"},{"en":"Consistent customer experience across channels builds trust.","zh-TW":"跨渠道一致的客戶體驗建立信任。"}]', 'phrasal verb'),
('retention rate', '', '', '[{"en":"Improving the user interface increased retention rate by 15%.","zh-TW":"改善用戶介面使留存率提高了15%。"},{"en":"High employee retention rates reflect strong company culture.","zh-TW":"高員工留存率反映了強大的公司文化。"}]', 'phrasal verb'),
('drip campaign', '', '', '[{"en":"The drip campaign guided prospects through the 30-day trial period.","zh-TW":"滴灌行銷活動引導潛在客戶完成30天試用期。"},{"en":"A well-designed drip campaign increases conversion rates.","zh-TW":"精心設計的滴灌行銷活動提高了轉換率。"}]', 'phrasal verb'),
('distribution channel', '', '', '[{"en":"The company added e-commerce as a new distribution channel.","zh-TW":"公司將電子商務作為新的銷售通路。"},{"en":"Indirect distribution channels use intermediaries to reach customers.","zh-TW":"間接配銷渠道使用中間商觸達客戶。"}]', 'phrasal verb'),
('channel partner', '', '', '[{"en":"Channel partners extend the company''s reach into new markets.","zh-TW":"通路合作夥伴將公司的覆蓋範圍擴展至新市場。"},{"en":"The channel partner program includes training and marketing support.","zh-TW":"通路合作夥伴計劃包括培訓和行銷支援。"}]', 'phrasal verb'),
('penetration pricing', '', '', '[{"en":"Penetration pricing helped the new service gain 100,000 users quickly.","zh-TW":"滲透定價幫助新服務迅速獲得了100,000名用戶。"},{"en":"The risk of penetration pricing is thin margins early on.","zh-TW":"滲透定價的風險是早期利潤率薄。"}]', 'phrasal verb'),
('burndown chart', '', '', '[{"en":"The burndown chart showed the team was ahead of schedule.","zh-TW":"燃盡圖顯示團隊超前於計劃。"},{"en":"A flat burndown chart indicates work is not being completed.","zh-TW":"平坦的燃盡圖表明工作沒有被完成。"}]', 'phrasal verb'),
('corrective action', '', '', '[{"en":"Corrective action was implemented to prevent the defect from recurring.","zh-TW":"採取了矯正措施以防止缺陷再次發生。"},{"en":"The audit required corrective action on five compliance issues.","zh-TW":"審計要求對五個合規問題採取矯正措施。"}]', 'phrasal verb'),
('preventive action', '', '', '[{"en":"Preventive action was taken after identifying a potential system vulnerability.","zh-TW":"在識別出潛在系統漏洞後採取了預防措施。"},{"en":"CAPA combines corrective and preventive action to improve quality.","zh-TW":"CAPA結合矯正和預防措施以提高品質。"}]', 'phrasal verb'),
('data visualization', '', '', '[{"en":"Data visualization made complex sales trends easy to understand.","zh-TW":"資料視覺化使複雜的銷售趨勢易於理解。"},{"en":"Interactive data visualization enables faster business decisions.","zh-TW":"互動式資料視覺化實現更快的商業決策。"}]', 'phrasal verb'),
('agenda item', '', '', '[{"en":"The merger was added as the first agenda item for the board meeting.","zh-TW":"合併被列為董事會議的第一個議程項目。"},{"en":"All participants may suggest agenda items before the meeting.","zh-TW":"所有與會者可在會議前提議議程項目。"}]', 'phrasal verb'),
('status update', '', '', '[{"en":"She provided a status update on the project every Friday.","zh-TW":"她每週五提供項目進度更新。"},{"en":"The client requested a daily status update during the critical phase.","zh-TW":"客戶在關鍵階段要求每日狀態更新。"}]', 'phrasal verb'),
('progress report', '', '', '[{"en":"The progress report showed 70% of tasks were completed on time.","zh-TW":"進度報告顯示70%的任務按時完成。"},{"en":"Monthly progress reports are submitted to the steering committee.","zh-TW":"月度進度報告提交給指導委員會。"}]', 'phrasal verb'),
('issue log', '', '', '[{"en":"The project manager maintained an issue log throughout the build phase.","zh-TW":"項目經理在整個建設階段維護問題記錄冊。"},{"en":"All open issues in the log must be resolved before go-live.","zh-TW":"記錄冊中的所有未解決問題必須在上線前解決。"}]', 'phrasal verb'),
('resource planning', '', '', '[{"en":"Resource planning ensured the team had the right skills at each phase.","zh-TW":"資源規劃確保了團隊在每個階段都具備正確的技能。"},{"en":"Poor resource planning caused delays in the critical path.","zh-TW":"糟糕的資源規劃導致了關鍵路徑上的延遲。"}]', 'phrasal verb'),
('quality control', '', '', '[{"en":"Rigorous quality control reduced defect rates to under 1%.","zh-TW":"嚴格的品質管制將缺陷率降至1%以下。"},{"en":"Quality control inspectors check every batch before shipment.","zh-TW":"品質管制檢查員在裝運前檢查每個批次。"}]', 'phrasal verb'),
('internal rate of return', '', '', '[{"en":"The project''s internal rate of return exceeded the cost of capital.","zh-TW":"項目的內部收益率超過了資本成本。"},{"en":"Investors compare IRR to their required return to evaluate investments.","zh-TW":"投資者將內部收益率與所需回報率比較以評估投資。"}]', 'phrasal verb'),
('letter of credit', '', '', '[{"en":"The exporter required a letter of credit before shipping goods.","zh-TW":"出口商在發貨前要求開立信用狀。"},{"en":"Letters of credit reduce payment risk in international trade.","zh-TW":"信用狀降低了國際貿易中的付款風險。"}]', 'phrasal verb'),
('line of credit', '', '', '[{"en":"The company used its line of credit to cover seasonal cash shortfalls.","zh-TW":"公司使用信用額度填補季節性現金短缺。"},{"en":"Maintaining an unused line of credit provides financial flexibility.","zh-TW":"保持未使用的信用額度提供財務靈活性。"}]', 'phrasal verb'),
('journal entry', '', '', '[{"en":"The accountant posted a journal entry to record the accrued expense.","zh-TW":"會計師過帳了一筆記錄應計費用的分錄。"},{"en":"Year-end adjusting journal entries ensure accurate financial statements.","zh-TW":"年末調整分錄確保財務報表的準確性。"}]', 'phrasal verb'),
('tax expense', '', '', '[{"en":"Tax expense reduced net profit by $2 million this year.","zh-TW":"稅務費用今年使淨利潤減少了200萬美元。"},{"en":"Deferred tax affects the total tax expense reported in the accounts.","zh-TW":"遞延稅影響帳目中報告的總稅務費用。"}]', 'phrasal verb'),
('income tax', '', '', '[{"en":"Corporate income tax is charged at 25% under the new rules.","zh-TW":"根據新規定，企業所得稅率為25%。"},{"en":"The company filed its income tax return before the deadline.","zh-TW":"公司在截止日期前申報了所得稅。"}]', 'phrasal verb'),
('cash flow statement', '', '', '[{"en":"The cash flow statement showed strong operating cash generation.","zh-TW":"現金流量表顯示了強勁的營業現金產生。"},{"en":"Investors use the cash flow statement to assess liquidity.","zh-TW":"投資者使用現金流量表評估流動性。"}]', 'phrasal verb'),
('financial statement', '', '', '[{"en":"Financial statements are required by law for listed companies.","zh-TW":"上市公司依法須編制財務報表。"},{"en":"Investors analyze financial statements to assess a company''s health.","zh-TW":"投資者分析財務報表以評估公司的健康狀況。"}]', 'phrasal verb'),
('operating lease', '', '', '[{"en":"Office space is often leased under an operating lease arrangement.","zh-TW":"辦公空間通常通過營業租賃安排租用。"},{"en":"Under new accounting standards, operating leases appear on the balance sheet.","zh-TW":"根據新會計標準，營業租賃出現在資產負債表上。"}]', 'phrasal verb'),
('finance lease', '', '', '[{"en":"The machinery was acquired under a five-year finance lease.","zh-TW":"機械設備通過五年融資租賃取得。"},{"en":"Finance leases create both an asset and a liability on the balance sheet.","zh-TW":"融資租賃在資產負債表上同時產生資產和負債。"}]', 'phrasal verb'),
('stock exchange', '', '', '[{"en":"The company listed its shares on the New York Stock Exchange.","zh-TW":"公司在紐約證券交易所上市。"},{"en":"Stock exchange regulations ensure fair trading practices.","zh-TW":"證券交易所法規確保公平的交易實踐。"}]', 'phrasal verb'),
('conference call', '', '', '[{"en":"The weekly conference call aligns teams across three time zones.","zh-TW":"每週電話會議協調三個時區的團隊。"},{"en":"The conference call was recorded for those who could not attend.","zh-TW":"電話會議被錄製下來供無法出席者收聽。"}]', 'phrasal verb'),
('video conference', '', '', '[{"en":"The international team held a video conference every Monday morning.","zh-TW":"國際團隊每週一早上舉行視訊會議。"},{"en":"Video conferencing tools became essential during remote work.","zh-TW":"視訊會議工具在遠端工作期間變得至關重要。"}]', 'phrasal verb'),
('executive summary', '', '', '[{"en":"The executive summary allowed the board to grasp the key points quickly.","zh-TW":"執行摘要讓董事會快速掌握了要點。"},{"en":"A well-written executive summary is essential for business proposals.","zh-TW":"精心撰寫的執行摘要對商業提案至關重要。"}]', 'phrasal verb'),
('quarterly review', '', '', '[{"en":"The quarterly review showed all KPIs were on track.","zh-TW":"季度審查顯示所有關鍵績效指標都在正軌上。"},{"en":"Leadership presents the quarterly review to the board each quarter.","zh-TW":"領導層每季向董事會呈報季度審查。"}]', 'phrasal verb'),
('annual general meeting', '', '', '[{"en":"Shareholders voted on the dividend proposal at the annual general meeting.","zh-TW":"股東在年度股東大會上對股利提案進行了投票。"},{"en":"The CEO presented the annual report at the AGM.","zh-TW":"執行長在年度股東大會上呈報了年報。"}]', 'phrasal verb'),
('free trade agreement', '', '', '[{"en":"The free trade agreement eliminated tariffs on agricultural goods.","zh-TW":"自由貿易協定消除了農產品關稅。"},{"en":"Both countries benefit from the terms of the free trade agreement.","zh-TW":"兩國都受益於自由貿易協定的條款。"}]', 'phrasal verb'),
('trade secret', '', '', '[{"en":"The formula is a closely guarded trade secret.","zh-TW":"這個配方是一個嚴格保守的商業機密。"},{"en":"Employees sign NDAs to protect the company''s trade secrets.","zh-TW":"員工簽署保密協議以保護公司的商業機密。"}]', 'phrasal verb'),
('foreign exchange', '', '', '[{"en":"Foreign exchange risk was hedged through forward contracts.","zh-TW":"外匯風險通過遠期合約進行對沖。"},{"en":"The company reported a foreign exchange loss due to the weak dollar.","zh-TW":"由於美元疲軟，公司報告了外匯損失。"}]', 'phrasal verb'),
('breach of contract', '', '', '[{"en":"The supplier''s failure to deliver on time constituted breach of contract.","zh-TW":"供應商未能按時交付構成違約。"},{"en":"The company sued for breach of contract and was awarded damages.","zh-TW":"公司以違約為由提起訴訟並獲得損害賠償。"}]', 'phrasal verb'),
('liability clause', '', '', '[{"en":"The liability clause capped damages at 12 months of contract value.","zh-TW":"責任條款將損害賠償上限設定為合同價值的12個月。"},{"en":"Lawyers carefully reviewed the liability clause before signing.","zh-TW":"律師在簽署前仔細審查了責任條款。"}]', 'phrasal verb'),
('force majeure', '', '', '[{"en":"The pandemic was declared a force majeure event by the court.","zh-TW":"法院宣布疫情為不可抗力事件。"},{"en":"The force majeure clause exempted the supplier from penalty.","zh-TW":"不可抗力條款免除了供應商的罰款。"}]', 'phrasal verb'),
('due diligence report', '', '', '[{"en":"The due diligence report identified three significant risk areas.","zh-TW":"盡職調查報告識別了三個重要風險領域。"},{"en":"Investors rely on the due diligence report to inform acquisition decisions.","zh-TW":"投資者依賴盡職調查報告做出收購決策。"}]', 'phrasal verb'),
('managing director', '', '', '[{"en":"The managing director oversees all company operations.","zh-TW":"董事總經理監督所有公司運營。"},{"en":"She was named managing director of the Asia-Pacific division.","zh-TW":"她被任命為亞太區董事總經理。"}]', 'phrasal verb'),
('executive committee', '', '', '[{"en":"The executive committee approved the new acquisition strategy.","zh-TW":"執行委員會批准了新的收購策略。"},{"en":"Major decisions are escalated to the executive committee for approval.","zh-TW":"重大決策被上報執行委員會審批。"}]', 'phrasal verb'),
('strategic planning', '', '', '[{"en":"Strategic planning sessions are held annually at the executive retreat.","zh-TW":"戰略規劃會議每年在高管靜修時舉行。"},{"en":"Effective strategic planning ensures the company is prepared for future challenges.","zh-TW":"有效的戰略規劃確保公司為未來挑戰做好準備。"}]', 'phrasal verb'),
('corporate social responsibility', '', '', '[{"en":"The company''s CSR program funds education in local communities.","zh-TW":"公司的企業社會責任計劃資助當地社區的教育。"},{"en":"Investors increasingly consider corporate social responsibility in their decisions.","zh-TW":"投資者越來越多地在決策中考量企業社會責任。"}]', 'phrasal verb'),
('supply chain', '', '', '[{"en":"The pandemic exposed vulnerabilities in global supply chains.","zh-TW":"疫情暴露了全球供應鏈的脆弱性。"},{"en":"Diversifying the supply chain reduces dependency on single suppliers.","zh-TW":"多元化供應鏈降低了對單一供應商的依賴。"}]', 'phrasal verb'),
('lead time', '', '', '[{"en":"The supplier''s lead time was reduced from six weeks to two.","zh-TW":"供應商的前置時間從六週縮短至兩週。"},{"en":"Short lead times give manufacturers flexibility to respond to demand.","zh-TW":"短前置時間使製造商能靈活應對需求。"}]', 'phrasal verb'),
('vendor management', '', '', '[{"en":"Effective vendor management ensures consistent product quality.","zh-TW":"有效的供應商管理確保一致的產品品質。"},{"en":"The procurement team handles all vendor management activities.","zh-TW":"採購團隊處理所有供應商管理活動。"}]', 'phrasal verb'),
('cloud computing', '', '', '[{"en":"Cloud computing enabled the startup to scale without heavy infrastructure investment.","zh-TW":"雲端運算使新創公司能夠在不大量基礎設施投資的情況下擴展。"},{"en":"Security is a top concern when adopting cloud computing.","zh-TW":"採用雲端運算時，安全性是首要關注點。"}]', 'phrasal verb'),
('data analytics', '', '', '[{"en":"Data analytics revealed patterns in customer purchasing behavior.","zh-TW":"數據分析揭示了客戶購買行為的模式。"},{"en":"The company uses data analytics to optimize its marketing spend.","zh-TW":"公司使用數據分析優化其行銷支出。"}]', 'phrasal verb'),
('artificial intelligence', '', '', '[{"en":"Artificial intelligence is transforming how businesses make decisions.","zh-TW":"人工智慧正在改變企業的決策方式。"},{"en":"The company deployed AI to improve customer service response times.","zh-TW":"公司部署人工智慧以改善客戶服務響應時間。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('machine learning', '', '', '[{"en":"Machine learning models improved fraud detection accuracy.","zh-TW":"機器學習模型提高了欺詐偵測的準確性。"},{"en":"The recommendation engine uses machine learning to personalize content.","zh-TW":"推薦引擎使用機器學習來個人化內容。"}]', 'phrasal verb'),
('customer service', '', '', '[{"en":"Excellent customer service drives repeat business and referrals.","zh-TW":"出色的客戶服務推動了回頭客和推薦業務。"},{"en":"The customer service team handles over 500 inquiries daily.","zh-TW":"客戶服務團隊每天處理超過500個查詢。"}]', 'phrasal verb'),
('customer satisfaction', '', '', '[{"en":"Customer satisfaction scores improved after the product update.","zh-TW":"產品更新後客戶滿意度分數有所提高。"},{"en":"High customer satisfaction leads to increased loyalty and referrals.","zh-TW":"高客戶滿意度帶來更高的忠誠度和推薦率。"}]', 'phrasal verb'),
('help desk', '', '', '[{"en":"Users submit tickets to the help desk for technical issues.","zh-TW":"用戶向服務台提交技術問題工單。"},{"en":"The help desk resolved 95% of issues on first contact.","zh-TW":"服務台在第一次接觸時解決了95%的問題。"}]', 'phrasal verb'),
('onboarding experience', '', '', '[{"en":"A smooth onboarding experience reduces early customer churn.","zh-TW":"順暢的開通體驗減少了早期客戶流失。"},{"en":"The app''s onboarding experience guided users through key features.","zh-TW":"應用程式的入門體驗引導用戶了解關鍵功能。"}]', 'phrasal verb'),
('service recovery', '', '', '[{"en":"Swift service recovery turned the unhappy customer into a loyal advocate.","zh-TW":"迅速的服務補救將不滿意的客戶轉變為忠實的擁護者。"},{"en":"Service recovery training helps frontline staff handle complaints.","zh-TW":"服務補救培訓幫助前線員工處理投訴。"}]', 'phrasal verb'),
('complaint handling', '', '', '[{"en":"Efficient complaint handling can strengthen customer relationships.","zh-TW":"有效的投訴處理可以加強客戶關係。"},{"en":"All customer complaints must be acknowledged within 24 hours.","zh-TW":"所有客戶投訴必須在24小時內得到確認。"}]', 'phrasal verb'),
('time management', '', '', '[{"en":"Good time management allows professionals to meet multiple deadlines.","zh-TW":"良好的時間管理讓專業人士能夠達到多個截止日期。"},{"en":"She took a course on time management to boost her productivity.","zh-TW":"她參加了時間管理課程以提高生產力。"}]', 'phrasal verb'),
('communication skills', '', '', '[{"en":"Excellent communication skills are essential for leadership roles.","zh-TW":"出色的溝通技巧對領導職位至關重要。"},{"en":"She was promoted in part due to her strong communication skills.","zh-TW":"她部分因其強大的溝通技巧而獲得晉升。"}]', 'phrasal verb'),
('professional development', '', '', '[{"en":"The company offers an annual budget for employee professional development.","zh-TW":"公司為員工職業發展提供年度預算。"},{"en":"Professional development is essential for staying current in a rapidly changing field.","zh-TW":"在快速變化的領域保持競爭力，職業發展至關重要。"}]', 'phrasal verb'),
('work ethic', '', '', '[{"en":"Her strong work ethic was recognized at the performance review.","zh-TW":"她強烈的敬業精神在績效評估中得到了認可。"},{"en":"A strong work ethic is one of the most sought-after qualities in candidates.","zh-TW":"強烈的敬業精神是候選人最受歡迎的品質之一。"}]', 'phrasal verb'),
('commercial property', '', '', '[{"en":"The company acquired commercial property in the city center.","zh-TW":"公司收購了市中心的商業地產。"},{"en":"Commercial property values fell during the economic downturn.","zh-TW":"經濟低迷期間商業地產價值下降。"}]', 'phrasal verb'),
('office space', '', '', '[{"en":"The company leased new office space to accommodate growth.","zh-TW":"公司租用了新辦公空間以適應增長需求。"},{"en":"Flexible office space arrangements have become popular post-pandemic.","zh-TW":"靈活的辦公空間安排在疫情後變得流行。"}]', 'phrasal verb'),
('lease agreement', '', '', '[{"en":"The lease agreement runs for five years with renewal options.","zh-TW":"租約為期五年，並有續約選擇權。"},{"en":"The lease agreement specifies rent, maintenance responsibilities, and notice periods.","zh-TW":"租約規定了租金、維護責任和通知期。"}]', 'phrasal verb'),
('coworking space', '', '', '[{"en":"Startups often begin in coworking spaces to keep costs low.","zh-TW":"新創公司通常從共享辦公空間開始以降低成本。"},{"en":"Coworking spaces provide networking opportunities and amenities.","zh-TW":"共享辦公空間提供社交機會和設施。"}]', 'phrasal verb'),
('compound interest', '', '', '[{"en":"Compound interest makes savings grow exponentially over time.","zh-TW":"複利使儲蓄隨時間呈指數增長。"},{"en":"The effect of compound interest is most powerful over long periods.","zh-TW":"複利的效應在長期內最為強大。"}]', 'phrasal verb'),
('dividend reinvestment', '', '', '[{"en":"A dividend reinvestment plan compounds returns over time.","zh-TW":"股利再投資計劃隨時間複利增長回報。"},{"en":"She enrolled in the dividend reinvestment program to grow her holdings.","zh-TW":"她加入了股利再投資計劃以增加持股。"}]', 'phrasal verb'),
('market analysis', '', '', '[{"en":"The market analysis identified a gap in the mid-range product segment.","zh-TW":"市場分析識別了中端產品市場的空缺。"},{"en":"Regular market analysis helps businesses stay ahead of trends.","zh-TW":"定期市場分析幫助企業保持領先趨勢。"}]', 'phrasal verb'),
('competitive analysis', '', '', '[{"en":"The competitive analysis revealed that the company was priced too high.","zh-TW":"競爭分析顯示公司定價過高。"},{"en":"A SWOT analysis is a common tool in competitive analysis.","zh-TW":"SWOT分析是競爭分析中的常用工具。"}]', 'phrasal verb'),
('SWOT analysis', '', '', '[{"en":"The SWOT analysis highlighted the company''s strong brand as a key strength.","zh-TW":"SWOT分析強調了公司強大品牌作為關鍵優勢。"},{"en":"SWOT analysis informed the board''s strategic planning session.","zh-TW":"SWOT分析為董事會的策略規劃會議提供了依據。"}]', 'phrasal verb'),
('economic cycle', '', '', '[{"en":"Businesses must plan for all phases of the economic cycle.","zh-TW":"企業必須為經濟周期的所有階段做好規劃。"},{"en":"Defensive stocks tend to perform well regardless of the economic cycle.","zh-TW":"防禦型股票往往在經濟周期的各個階段都表現良好。"}]', 'phrasal verb'),
('economic growth', '', '', '[{"en":"Strong economic growth led to increased business investment.","zh-TW":"強勁的經濟增長帶來了增加的商業投資。"},{"en":"Technology is a key driver of long-term economic growth.","zh-TW":"技術是長期經濟增長的關鍵驅動力。"}]', 'phrasal verb'),
('market trend', '', '', '[{"en":"The market trend toward sustainability is reshaping consumer preferences.","zh-TW":"向永續性轉變的市場趨勢正在重塑消費者偏好。"},{"en":"Analysts track market trends to forecast future demand.","zh-TW":"分析師追蹤市場趨勢以預測未來需求。"}]', 'phrasal verb'),
('pay stub', '', '', '[{"en":"She reviewed her pay stub to verify the overtime payment.","zh-TW":"她查看薪資單以核實加班費。"},{"en":"Pay stubs are required as proof of income for loan applications.","zh-TW":"薪資單作為貸款申請的收入證明是必需的。"}]', 'phrasal verb'),
('performance bonus', '', '', '[{"en":"The team shared a performance bonus after exceeding annual targets.","zh-TW":"團隊在超越年度目標後共同分享了績效獎金。"},{"en":"Performance bonuses are tied to individual and company results.","zh-TW":"績效獎金與個人和公司業績掛鈎。"}]', 'phrasal verb'),
('appraisal cycle', '', '', '[{"en":"The annual appraisal cycle runs from January to December.","zh-TW":"年度考核週期從一月到十二月。"},{"en":"Employees set goals at the start of each appraisal cycle.","zh-TW":"員工在每個考核週期開始時設定目標。"}]', 'phrasal verb'),
('job posting', '', '', '[{"en":"The job posting attracted over 300 applications within a week.","zh-TW":"職位公告在一週內吸引了300多份申請。"},{"en":"Internal job postings encourage employees to grow within the company.","zh-TW":"內部職位公告鼓勵員工在公司內部成長。"}]', 'phrasal verb'),
('cover letter', '', '', '[{"en":"A compelling cover letter can set a candidate apart from other applicants.","zh-TW":"一封引人注目的求職信能讓候選人從其他申請者中脫穎而出。"},{"en":"She addressed the cover letter directly to the hiring manager.","zh-TW":"她將求職信直接寄給招聘主管。"}]', 'phrasal verb'),
('tax deduction', '', '', '[{"en":"Business travel expenses are eligible for a tax deduction.","zh-TW":"商務旅行費用可申請稅務扣除。"},{"en":"She claimed a tax deduction for her home office expenses.","zh-TW":"她申請了家庭辦公室費用的稅務扣除。"}]', 'phrasal verb'),
('tax credit', '', '', '[{"en":"The company claimed an R&D tax credit for its innovation program.","zh-TW":"公司為其創新計劃申請了研發稅收抵免。"},{"en":"A tax credit directly reduces the amount of tax owed.","zh-TW":"稅收抵免直接減少應繳稅款。"}]', 'phrasal verb'),
('tax return', '', '', '[{"en":"The company filed its corporate tax return before the April deadline.","zh-TW":"公司在四月截止日期前提交了企業稅務申報表。"},{"en":"Tax returns must be accurate to avoid penalties from the tax authority.","zh-TW":"稅務申報表必須準確，以避免稅務機關的罰款。"}]', 'phrasal verb'),
('audit trail', '', '', '[{"en":"The audit trail showed every change made to the financial records.","zh-TW":"審計追蹤顯示了對財務記錄所做的每一項更改。"},{"en":"A complete audit trail is required for compliance purposes.","zh-TW":"合規目的需要完整的審計追蹤。"}]', 'phrasal verb'),
('internal control', '', '', '[{"en":"Strong internal controls reduce the risk of financial misstatement.","zh-TW":"強大的內部控制降低了財務錯報的風險。"},{"en":"The auditors identified a weakness in the internal controls.","zh-TW":"審計師識別了內部控制的弱點。"}]', 'phrasal verb'),
('accounts reconciliation', '', '', '[{"en":"Accounts reconciliation revealed an unrecorded transaction.","zh-TW":"帳戶對帳發現了一筆未記錄的交易。"},{"en":"IT tools have automated the accounts reconciliation process.","zh-TW":"IT工具已自動化了帳戶對帳流程。"}]', 'phrasal verb'),
('accrual accounting', '', '', '[{"en":"Most listed companies report under the accrual accounting basis.","zh-TW":"大多數上市公司採用應計制會計報告。"},{"en":"Accrual accounting gives a more accurate picture of financial health.","zh-TW":"應計制會計提供了更準確的財務狀況圖像。"}]', 'phrasal verb'),
('due diligence checklist', '', '', '[{"en":"The due diligence checklist covered legal, financial, and operational areas.","zh-TW":"盡職調查清單涵蓋了法律、財務和運營領域。"},{"en":"A comprehensive checklist ensures no critical area is overlooked.","zh-TW":"全面的清單確保沒有關鍵領域被忽視。"}]', 'phrasal verb'),
('burn rate', '', '', '[{"en":"The startup''s burn rate was $200,000 per month.","zh-TW":"新創公司每月的現金消耗率為20萬美元。"},{"en":"Investors closely monitor burn rate to ensure sufficient runway.","zh-TW":"投資者密切監控燒錢速度以確保足夠的資金跑道。"}]', 'phrasal verb'),
('Series A', '', '', '[{"en":"The startup raised $10 million in a Series A funding round.","zh-TW":"這家新創公司在A輪融資中籌集了1000萬美元。"},{"en":"After closing Series A, the team expanded to 50 employees.","zh-TW":"A輪融資完成後，團隊擴大到50名員工。"}]', 'phrasal verb'),
('equity financing', '', '', '[{"en":"The company opted for equity financing to avoid increasing its debt.","zh-TW":"公司選擇股權融資以避免增加債務。"},{"en":"Equity financing dilutes existing shareholders'' ownership stake.","zh-TW":"股權融資稀釋了現有股東的持股比例。"}]', 'phrasal verb'),
('debt financing', '', '', '[{"en":"Debt financing allows companies to raise capital without diluting ownership.","zh-TW":"債務融資允許公司在不稀釋所有權的情況下籌集資金。"},{"en":"High debt financing increases financial risk during downturns.","zh-TW":"高債務融資在經濟下滑期間增加了財務風險。"}]', 'phrasal verb'),
('due date', '', '', '[{"en":"The invoice has a due date of 30 days from the date of issue.","zh-TW":"發票的到期日為開票日起30天。"},{"en":"Missing the due date may result in late payment penalties.","zh-TW":"錯過到期日可能導致逾期付款罰款。"}]', 'phrasal verb'),
('product development', '', '', '[{"en":"The product development team worked closely with customers to refine features.","zh-TW":"產品開發團隊與客戶密切合作以完善功能。"},{"en":"Rapid product development is essential in competitive technology markets.","zh-TW":"在競爭激烈的科技市場，快速的產品開發至關重要。"}]', 'phrasal verb'),
('user story', '', '', '[{"en":"Each user story describes what a specific type of user wants to accomplish.","zh-TW":"每個用戶故事描述了特定類型用戶想要完成的事情。"},{"en":"The product team wrote 50 user stories for the new release.","zh-TW":"產品團隊為新版本編寫了50個用戶故事。"}]', 'phrasal verb'),
('cap table', '', '', '[{"en":"The cap table was updated after each funding round.","zh-TW":"資本表在每輪融資後進行更新。"},{"en":"A messy cap table can complicate future fundraising.","zh-TW":"雜亂的資本表可能使未來融資複雜化。"}]', 'phrasal verb'),
('vesting schedule', '', '', '[{"en":"The stock options vest over a four-year vesting schedule.","zh-TW":"股票選擇權按照四年歸屬計劃解鎖。"},{"en":"He left before his options fully vested under the vesting schedule.","zh-TW":"他在股票選擇權按歸屬計劃完全解鎖前離職了。"}]', 'phrasal verb'),
('cliff vesting', '', '', '[{"en":"Employees receive no shares until the one-year cliff vesting date.","zh-TW":"員工在一年懸崖式歸屬日期前不會獲得任何股票。"},{"en":"Cliff vesting encourages employees to stay through the initial period.","zh-TW":"懸崖式歸屬鼓勵員工度過初始期。"}]', 'phrasal verb'),
('primary market', '', '', '[{"en":"Companies raise capital in the primary market through IPOs.","zh-TW":"公司通過首次公開募股在一級市場籌集資金。"},{"en":"Primary market transactions involve the issuing company directly.","zh-TW":"一級市場交易直接涉及發行公司。"}]', 'phrasal verb'),
('blue ocean strategy', '', '', '[{"en":"The startup found a blue ocean by targeting an entirely new customer segment.","zh-TW":"新創公司通過針對全新客戶群找到了藍海。"},{"en":"Blue ocean strategy focuses on value innovation rather than competition.","zh-TW":"藍海策略著重於價值創新而非競爭。"}]', 'phrasal verb'),
('competitive landscape', '', '', '[{"en":"Mapping the competitive landscape revealed three key rivals.","zh-TW":"繪製競爭格局圖揭示了三個主要競爭對手。"},{"en":"The competitive landscape shifted dramatically after the new entrant arrived.","zh-TW":"新進入者到來後，競爭格局發生了巨大變化。"}]', 'phrasal verb'),
('market entry', '', '', '[{"en":"The market entry strategy focused on partnerships with local distributors.","zh-TW":"市場進入策略側重於與當地分銷商的合作關係。"},{"en":"High capital requirements create barriers to market entry.","zh-TW":"高資本要求造成了市場進入壁壘。"}]', 'phrasal verb');